CREATE TABLE IF NOT EXISTS rooms (code TEXT PRIMARY KEY, made INTEGER NOT NULL, alive INTEGER NOT NULL, version INTEGER NOT NULL, max INTEGER NOT NULL, ip TEXT NOT NULL, host_key TEXT NOT NULL, host_name TEXT NOT NULL, host_addrs TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (code TEXT NOT NULL, slot INTEGER NOT NULL, key TEXT NOT NULL, name TEXT NOT NULL, addrs TEXT NOT NULL, ip TEXT NOT NULL, same INTEGER NOT NULL, joined INTEGER NOT NULL, PRIMARY KEY (code, slot));
CREATE TABLE IF NOT EXISTS used (what TEXT NOT NULL, slot INTEGER NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (what, slot));
